/**
 * @file Unit tests for the surface-side client paths the security suite leaves out: a call made
 * before the host's init waits for it, malformed messages and failure shapes are ignored, the
 * bootstrap envelope is read only while current, a silent host times out, and `ready` settles on init.
 * The parent window and message listener are typed fakes; timers are vitest's fake timers.
 */
import { afterEach, describe, expect, test, vi } from 'vitest';
import { AdminSurfaceCallError, createAdminSurfaceClient, type AdminSurfaceIncomingMessage, type AdminSurfaceParentPort } from '../surface-client.js';

const HOST = 'https://host.example.com';
const BASE = { protocol: 'jini.admin-surface', version: 1 } as const;

afterEach(() => { vi.useRealTimers(); });

function harness(optional: { nowMs?: () => number; timeoutMs?: number } = {}) {
  const posted: Array<{ message: unknown; targetOrigin: string }> = [];
  const parent: AdminSurfaceParentPort = { postMessage: (message, targetOrigin) => { posted.push({ message, targetOrigin }); } };
  let deliver: (event: AdminSurfaceIncomingMessage) => void = () => undefined;
  const client = createAdminSurfaceClient({ parent, listen: (handler) => { deliver = handler; return () => { deliver = () => undefined; }; } }, optional);
  const send = (data: unknown) => deliver({ origin: HOST, source: parent, data });
  const init = (data: Record<string, unknown> = {}) => send({ ...BASE, kind: 'init', mountId: 'm-1', ...data });
  const respond = (data: Record<string, unknown>) => send({ ...BASE, kind: 'action-response', mountId: 'm-1', requestId: 'r1', ...data });
  return { posted, client, send, init, respond };
}

describe('before init', () => {
  test('a call made before init is posted once init arrives', async () => {
    const { posted, client, init, respond } = harness();
    const pending = client.call({ action: 'save', payload: { a: 1 } });
    await Promise.resolve();
    expect(posted).toEqual([]);
    init();
    await client.ready;
    await Promise.resolve();
    expect(posted).toEqual([{ message: { ...BASE, kind: 'action-request', mountId: 'm-1', requestId: 'r1', action: 'save', payload: { a: 1 } }, targetOrigin: HOST }]);
    respond({ ok: true, result: 'saved' });
    await expect(pending).resolves.toBe('saved');
  });

  test('ready resolves on the first init', async () => {
    const { client, init } = harness();
    init();
    await expect(client.ready).resolves.toBeUndefined();
  });

  test('an init without a string mountId is ignored', async () => {
    const { client, init, posted } = harness();
    init({ mountId: 7 });
    init();
    const opened = client.openLink({ url: 'https://docs.example.com/a' });
    await client.ready;
    await Promise.resolve();
    expect(posted[0]).toMatchObject({ message: { kind: 'open-link', mountId: 'm-1', url: 'https://docs.example.com/a' } });
    client.close();
    await expect(opened).rejects.toMatchObject({ code: 'closed' });
  });

  test.each([[null], ['init'], [42]])('a non-object message %j is ignored', async (data) => {
    const { client, send, init, respond } = harness();
    send(data);
    init();
    const pending = client.call({ action: 'save', payload: {} });
    await client.ready;
    await Promise.resolve();
    respond({ ok: true, result: 'ok' });
    await expect(pending).resolves.toBe('ok');
  });
});

describe('responses', () => {
  test.each([
    ['a string error', { ok: false, error: 'denied' }],
    ['a null error', { ok: false, error: null }],
    ['an error missing retryable', { ok: false, error: { code: 'denied', message: 'No.' } }],
    ['ok without a result', { ok: true }],
    ['a non-boolean ok', { ok: 'yes', result: 1 }],
  ])('%s does not settle the call', async (_label, data) => {
    const { client, init, respond } = harness();
    init();
    const pending = client.call({ action: 'save', payload: {} });
    await Promise.resolve();
    respond(data);
    client.close();
    await expect(pending).rejects.toMatchObject({ code: 'closed', message: 'The surface was closed before the host answered.', retryable: false });
  });

  test('a well-formed failure rejects with a typed call error', async () => {
    const { client, init, respond } = harness();
    init();
    const pending = client.call({ action: 'save', payload: {} });
    await Promise.resolve();
    respond({ ok: false, error: { code: 'invalid-input', message: 'Fix the name.', retryable: false } });
    const error = await pending.catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(AdminSurfaceCallError);
    expect(error).toMatchObject({ name: 'AdminSurfaceCallError', code: 'invalid-input', message: 'Fix the name.', retryable: false });
  });

  test('a silent host times out as retryable after the configured time', async () => {
    vi.useFakeTimers();
    const { client, init } = harness({ timeoutMs: 500 });
    init();
    const pending = client.call({ action: 'save', payload: {} });
    const settled = pending.catch((caught: unknown) => caught);
    await Promise.resolve();
    await vi.advanceTimersByTimeAsync(499);
    await vi.advanceTimersByTimeAsync(1);
    await expect(settled).resolves.toMatchObject({ code: 'timeout', message: 'The host did not answer in time. Try again.', retryable: true });
  });

  test('a response after the timeout is ignored', async () => {
    vi.useFakeTimers();
    const { client, init, respond } = harness({ timeoutMs: 500 });
    init();
    const settled = client.call({ action: 'save', payload: {} }).then((value) => ({ value }), (error: unknown) => ({ error }));
    await Promise.resolve();
    await vi.advanceTimersByTimeAsync(500);
    respond({ ok: true, result: 'late' });
    await expect(settled).resolves.toMatchObject({ error: { code: 'timeout' } });
  });

  test('defaults to a 30-second timeout', async () => {
    vi.useFakeTimers();
    const { client, init } = harness();
    init();
    const settled = client.call({ action: 'save', payload: {} }).catch((caught: unknown) => caught);
    await Promise.resolve();
    await vi.advanceTimersByTimeAsync(29_999);
    let done = false;
    void settled.then(() => { done = true; });
    await Promise.resolve();
    expect(done).toBe(false);
    await vi.advanceTimersByTimeAsync(1);
    await expect(settled).resolves.toMatchObject({ code: 'timeout' });
  });
});

describe('bootstrap', () => {
  test('returns the data while the envelope is current', () => {
    const { client, init } = harness({ nowMs: () => 1_000 });
    init({ bootstrap: { expiresAt: 1_001, data: { sheet: 'A' } } });
    expect(client.bootstrap()).toEqual({ sheet: 'A' });
  });

  test('returns undefined once the envelope has expired', () => {
    const { client, init } = harness({ nowMs: () => 1_001 });
    init({ bootstrap: { expiresAt: 1_001, data: { sheet: 'A' } } });
    expect(client.bootstrap()).toBeUndefined();
  });

  test.each([['a string envelope', 'data'], ['a null envelope', null], ['an envelope without a numeric expiry', { expiresAt: '9', data: 1 }]])('returns undefined for %s', (_label, bootstrap) => {
    const { client, init } = harness({ nowMs: () => 0 });
    init({ bootstrap });
    expect(client.bootstrap()).toBeUndefined();
  });

  test('returns undefined before init', () => {
    expect(harness().client.bootstrap()).toBeUndefined();
  });

  test('reads the real clock by default', () => {
    const { client, init } = harness();
    init({ bootstrap: { expiresAt: Date.now() + 60_000, data: 'fresh' } });
    expect(client.bootstrap()).toBe('fresh');
  });
});

describe('browser-backed defaults (injected scope, no DOM)', () => {
  function fakeBrowser(optional: { withStyle?: boolean } = {}) {
    const observers: Array<{ kind: string; callback: () => void; observed: unknown[]; disconnected: boolean }> = [];
    const observer = (kind: string) => class {
      readonly entry: (typeof observers)[number];
      constructor(callback: () => void) { this.entry = { kind, callback, observed: [], disconnected: false }; observers.push(this.entry); }
      observe(_target: unknown, options?: Readonly<Record<string, boolean>>) { this.entry.observed.push(options ?? 'no-options'); }
      disconnect() { this.entry.disconnected = true; }
    };
    const listeners = new Map<string, () => void>();
    const body = {
      scrollHeight: 100, boxHeight: 100.4, margins: { marginTop: '8px', marginBottom: '' },
      getBoundingClientRect() { return { height: body.boxHeight }; },
      addEventListener(type: 'mouseover' | 'focusin', listener: () => void) { listeners.set(type, listener); },
      removeEventListener(type: 'mouseover' | 'focusin', listener: () => void) { if (listeners.get(type) === listener) listeners.delete(type); },
    };
    const styles: string[] = [];
    const root = { style: { setProperty: (name: string, value: string) => { styles.push(`${name}=${value}`); }, removeProperty: () => undefined }, setAttribute: (name: string, value: string) => { styles.push(`@${name}=${value}`); } };
    const browser = {
      document: { documentElement: root, body },
      ResizeObserver: observer('resize'), MutationObserver: observer('mutation'),
      ...(optional.withStyle === false ? {} : { getComputedStyle: () => body.margins }),
    };
    return { browser, body, listeners, observers, styles };
  }
  function start(browser: object) {
    const posted: unknown[] = [];
    let deliver: (event: AdminSurfaceIncomingMessage) => void = () => undefined;
    const parent: AdminSurfaceParentPort = { postMessage: (message) => { posted.push(message); } };
    const client = createAdminSurfaceClient({ parent, listen: (handler) => { deliver = handler; return () => undefined; } }, { browser });
    deliver({ origin: HOST, source: parent, data: { ...BASE, kind: 'init', mountId: 'm-1', theme: { scheme: 'dark', tokens: { '--jini-primary': '#000' } } } });
    return { client, heights: () => posted.map(message => (message as { height?: number }).height).filter(height => height !== undefined) };
  }

  test('measures the body (box height fraction and margins) on start, observers, hover and focus, and stops cleanly', () => {
    const fake = fakeBrowser();
    const { client, heights } = start(fake.browser);
    expect(heights()).toEqual([109]);
    expect(fake.observers.map(entry => [entry.kind, entry.observed])).toEqual([
      ['resize', ['no-options']], ['mutation', [{ subtree: true, childList: true, attributes: true, characterData: true }]],
    ]);
    fake.body.scrollHeight = 150;
    fake.body.margins = { marginTop: '', marginBottom: '2px' };
    fake.observers[0]!.callback();
    fake.body.scrollHeight = 160;
    fake.listeners.get('mouseover')!();
    fake.body.scrollHeight = 170;
    fake.listeners.get('focusin')!();
    expect(heights()).toEqual([109, 152, 162, 172]);
    client.close();
    expect(fake.observers.every(entry => entry.disconnected)).toBe(true);
    expect([...fake.listeners.keys()]).toEqual([]);
  });
  test('applies the init theme to the document root', () => {
    const fake = fakeBrowser();
    start(fake.browser);
    expect(fake.styles).toEqual(['--jini-primary=#000', 'color-scheme=dark', '@data-jini-scheme=dark']);
  });
  test('reports no height without a computed-style source, a body, or observers', () => {
    for (const browser of [fakeBrowser({ withStyle: false }).browser, { document: {} }, { document: { body: fakeBrowser().body } }, { document: { body: fakeBrowser().body }, ResizeObserver: fakeBrowser().browser.ResizeObserver }]) {
      expect(start(browser).heights()).toEqual([]);
    }
  });
});

src/__tests__/folder-zip-node.characteri.source:
import assert from "node:assert/strict";
import { constants } from "node:fs";
import path from "node:path";
import { beforeEach, test, vi } from "vitest";
import { FOLDER_MAX_FILES, FolderZipError, zipFolderFiles } from "../folder-zip.js";
import { zipLocalFolder } from "../folder-zip-node.js";

type Entry = { name: string; isDirectory(): boolean; isFile(): boolean };
type Handle = {
  stat(): Promise<{ size: number; isFile(): boolean }>;
  read(buffer: Buffer, offset: number, length: number, position: null): Promise<{ bytesRead: number }>;
  close(): Promise<void>;
};
const filesystem = vi.hoisted(() => ({
  realpath: vi.fn<(filename: string) => Promise<string>>(),
  lstat: vi.fn<(filename: string) => Promise<{ isDirectory(): boolean }>>(),
  opendir: vi.fn<(filename: string) => Promise<AsyncIterable<Entry>>>(),
  open: vi.fn<(filename: string, flags: number) => Promise<Handle>>(),
}));
vi.mock("node:fs/promises", () => filesystem);

const root = path.resolve("/picked");
let entries: Entry[];
let content: Buffer;
let info: { size: number; isFile(): boolean };
let cursor: number;
const handle = {
  stat: vi.fn<Handle["stat"]>(),
  read: vi.fn<Handle["read"]>(),
  close: vi.fn<Handle["close"]>(),
} satisfies Handle;

function entry(required: { name: string; kind?: "file" | "directory" | "special" }, _optional: Record<string, never> = {}): Entry {
  const kind = required.kind ?? "file";
  return { name: required.name, isDirectory: () => kind === "directory", isFile: () => kind === "file" };
}

async function* listing(required: { entries: Entry[] }, _optional: Record<string, never> = {}): AsyncIterable<Entry> {
  yield* required.entries;
}

beforeEach(() => {
  vi.resetAllMocks();
  entries = [entry({ name: "a" })];
  content = Buffer.from([1, 2]);
  info = { size: 2, isFile: () => true };
  cursor = 0;
  filesystem.realpath.mockImplementation(async filename => filename);
  filesystem.lstat.mockResolvedValue({ isDirectory: () => true });
  filesystem.opendir.mockImplementation(async () => listing({ entries }));
  filesystem.open.mockImplementation(async () => { cursor = 0; return handle; });
  handle.stat.mockImplementation(async () => info);
  handle.read.mockImplementation(async (buffer, offset, length) => {
    const count = content.copy(buffer, offset, cursor, cursor + Math.min(length, 1));
    cursor += count;
    return { bytesRead: count };
  });
  handle.close.mockResolvedValue(undefined);
});

const unreadable = { reason: "unreadable", message: "Could not read that folder. Try again." };

test("local reads retain partial chunks, stop at EOF and close the descriptor", async () => {
  const file = new File([new Uint8Array(content)], "a");
  Object.defineProperty(file, "webkitRelativePath", { value: "picked/a" });
  const expected = await zipFolderFiles({ files: [file], maxBytes: 1024 });
  assert.deepEqual(await zipLocalFolder({ path: root, maxBytes: 1024 }), new Uint8Array(await expected.arrayBuffer()));
  assert.equal(handle.read.mock.calls.length, 3);
  assert.deepEqual(handle.read.mock.calls.map(call => [call[1], call[2], call[3]]), [[0, 3, null], [1, 2, null], [2, 1, null]]);
  assert.equal(handle.close.mock.calls.length, 1);
  assert.deepEqual(filesystem.open.mock.calls, [[path.join(root, "a"), constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK]]);
});

test("an empty file is accepted after its EOF is confirmed", async () => {
  content = Buffer.alloc(0);
  info.size = 0;
  const bytes = await zipLocalFolder({ path: root, maxBytes: 100 });
  assert.equal(bytes.length, 100);
  assert.equal(handle.read.mock.calls.length, 1);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("nested directories are traversed and entries are sorted independently of enumeration order", async () => {
  filesystem.opendir.mockImplementation(async filename => listing({ entries: filename === root
    ? [entry({ name: "z" }), entry({ name: "dir", kind: "directory" }), entry({ name: "a" })]
    : [entry({ name: "b" })] }));
  const files = ["a", "dir/b", "z"].map(name => {
    const file = new File([new Uint8Array(content)], path.basename(name));
    Object.defineProperty(file, "webkitRelativePath", { value: `picked/${name}` });
    return file;
  });
  const expected = await zipFolderFiles({ files, maxBytes: 1024 });
  assert.deepEqual(await zipLocalFolder({ path: root, maxBytes: 1024 }), new Uint8Array(await expected.arrayBuffer()));
  assert.deepEqual(filesystem.opendir.mock.calls, [[root], [path.join(root, "dir")]]);
  assert.equal(handle.close.mock.calls.length, 3);
});

test("equal relative paths keep duplicate files in the archive", async () => {
  entries.push(entry({ name: "a" }));
  const bytes = await zipLocalFolder({ path: root, maxBytes: 1024 });
  assert.equal(new DataView(bytes.buffer).getUint16(bytes.length - 14, true), 2);
  assert.equal(handle.close.mock.calls.length, 2);
});

test("non-directories are refused before opening a directory", async () => {
  filesystem.lstat.mockResolvedValue({ isDirectory: () => false });
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.opendir.mock.calls.length, 0);
  assert.equal(filesystem.realpath.mock.calls.length, 1);
});

test("a directory whose real path changes is refused before enumeration", async () => {
  filesystem.realpath.mockResolvedValueOnce(root).mockResolvedValueOnce(path.resolve("/elsewhere"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.opendir.mock.calls.length, 0);
});

test("special entries are refused before opening a file", async () => {
  entries = [entry({ name: "link", kind: "special" })];
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.open.mock.calls.length, 0);
});

test("files whose real paths differ are refused before opening", async () => {
  filesystem.realpath.mockImplementation(async filename => filename === root ? root : path.resolve("/outside"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.open.mock.calls.length, 0);
});

test("an opened special file is refused and its descriptor is closed", async () => {
  info.isFile = () => false;
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.read.mock.calls.length, 0);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("cumulative raw sizes are bounded before the next allocation or read", async () => {
  entries.push(entry({ name: "b" }));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 3 }), {
    reason: "too-large", message: "Folder is over the upload limit.",
  });
  assert.equal(handle.read.mock.calls.length, 3);
  assert.equal(handle.close.mock.calls.length, 2);
});

test("growth beyond the stat size is detected with one extra byte and closes the file", async () => {
  info.size = 1;
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.read.mock.calls.length, 2);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("shrinkage below the stat size is refused and closes the file", async () => {
  info.size = 3;
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("read and stat failures are translated after closing the file", async () => {
  handle.read.mockRejectedValueOnce(new Error("read failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 1);
  handle.stat.mockRejectedValueOnce(new Error("stat failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 2);
});

test("close failures override a raw-size refusal and become unreadable", async () => {
  handle.close.mockRejectedValueOnce(new Error("close failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1 }), unreadable);
  assert.equal(handle.read.mock.calls.length, 0);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("native root, enumeration and open failures become unreadable refusals", async () => {
  filesystem.realpath.mockRejectedValueOnce(new Error("realpath failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  filesystem.opendir.mockRejectedValueOnce(new Error("opendir failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  filesystem.open.mockRejectedValueOnce(new Error("open failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 0);
});

test("existing FolderZipError instances are rethrown unchanged", async () => {
  const error = new FolderZipError("too-many", "original message");
  filesystem.realpath.mockRejectedValueOnce(error);
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), caught => caught === error);
});

test("the entry cap counts directories and refuses the next entry before opening it", async () => {
  entries = Array.from({ length: FOLDER_MAX_FILES + 1 }, (_, i) => entry({ name: String(i), kind: "directory" }));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), {
    reason: "too-many", message: "More than 4096 entries.",
  });
  assert.equal(filesystem.opendir.mock.calls.length, 1);
  assert.equal(filesystem.open.mock.calls.length, 0);
});

test("an empty traversal preserves the encoder's empty-folder refusal", async () => {
  entries = [];
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), {
    reason: "empty", message: "That folder is empty.",
  });
});

test("a parent swapped for a symlink after realpath can supply outside bytes (reported, not fixed)", async () => {
  const actual = await vi.importActual<typeof import("node:fs/promises")>("node:fs/promises");
  const { tmpdir } = await import("node:os");
  const temporary = await actual.realpath(await actual.mkdtemp(path.join(tmpdir(), "folder-zip-parent-race-")));
  try {
    const selected = path.join(temporary, "selected");
    const outside = path.join(temporary, "outside");
    await actual.mkdir(selected);
    await actual.mkdir(outside);
    await actual.writeFile(path.join(selected, "a"), "selected bytes");
    await actual.writeFile(path.join(outside, "a"), "outside bytes");
    filesystem.realpath.mockImplementation(filename => actual.realpath(filename));
    filesystem.lstat.mockImplementation(filename => actual.lstat(filename));
    filesystem.opendir.mockImplementation(filename => actual.opendir(filename));
    filesystem.open.mockImplementation(async (filename, flags) => {
      await actual.rename(selected, path.join(temporary, "original"));
      await actual.symlink(outside, selected);
      return actual.open(filename, flags);
    });
    const file = new File(["outside bytes"], "a");
    Object.defineProperty(file, "webkitRelativePath", { value: "picked/a" });
    const expected = await zipFolderFiles({ files: [file], maxBytes: 1024 });
    assert.deepEqual(await zipLocalFolder({ path: selected, maxBytes: 1024 }), new Uint8Array(await expected.arrayBuffer()));
  } finally { await actual.rm(temporary, { recursive: true, force: true }); }
});

