/**
 * @file Unit tests for the remaining edge paths across the admin-surface modules: action error
 * construction, the callback inbox's expiry sweep under a clock that steps backwards, a non-string
 * declared name, a non-object message, the init envelope with bootstrap, the safe default content
 * type, and a host status that omits its account label.
 */
import { describe, expect, test } from 'vitest';
import { WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import { AdminSurfaceActionError } from '../action-dispatcher.js';
import { createAdminSurfaceCallbackInbox } from '../callback-field-inbox.js';
import { parseAdminSurfaceCapabilityDeclarations } from '../capability-declarations.js';
import { defineAdminSurfaceContribution } from '../contribution.js';
import { parseAdminSurfacesFile, type AdminSurfaceDescriptor } from '../descriptor.js';
import { validateAdminSurfaceMessage } from '../host-validator.js';
import { adminSurfaceInitMessage } from '../protocol.js';
import { adminSurfaceFileHeaders, createAdminSurfaceBootstrap } from '../sandbox.js';
import { openAdminSurfaceCapabilitySession, type AdminSurfaceConnectionStatus } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

describe('AdminSurfaceActionError', () => {
  test('defaults to not retryable and carries no cause', () => {
    const error = new AdminSurfaceActionError({ code: 'sheet-missing', message: 'Pick the sheet again.' });
    expect(error).toMatchObject({ name: 'AdminSurfaceActionError', code: 'sheet-missing', message: 'Pick the sheet again.', retryable: false });
    expect('cause' in error).toBe(false);
  });

  test('keeps an explicit retryable flag and cause', () => {
    const cause = new Error('upstream 503');
    const error = new AdminSurfaceActionError({ code: 'retry-later', message: 'Try again shortly.' }, { retryable: true, cause });
    expect([error.retryable, error.cause]).toEqual([true, cause]);
  });
});

describe('callback inbox', () => {
  const key = (attemptId: string) => ({ workspaceId: 'w', pluginId: 'acme-office', connectionId: 'account', attemptId });
  const TTL = 10 * 60 * 1000;

  test('expired entries are swept before the cap, so a live entry is not evicted while expired ones remain', () => {
    // A wall clock can step backwards: entries deposited after the step expire before an older one.
    let now = 10_000;
    const inbox = createAdminSurfaceCallbackInbox({ now: () => now });
    inbox.deposit({ ...key('live'), fields: { 'picked-id': 'kept' } });
    now = 0;
    for (let index = 0; index < 255; index += 1) inbox.deposit({ ...key(`stale-${index}`), fields: {} });
    now = TTL;
    inbox.deposit({ ...key('new'), fields: {} });
    expect(inbox.take(key('live'))).toEqual({ 'picked-id': 'kept' });
  });

  test('when full of live entries, the oldest is dropped for a new one', () => {
    const inbox = createAdminSurfaceCallbackInbox({ now: () => 0 });
    for (let index = 0; index < 256; index += 1) inbox.deposit({ ...key(`a-${index}`), fields: { n: String(index) } });
    inbox.deposit({ ...key('newest'), fields: {} });
    expect([inbox.take(key('a-0')), inbox.take(key('a-1')), inbox.take(key('newest'))]).toEqual([null, { n: '1' }, {}]);
  });
});

describe('capability declarations', () => {
  test('start parameters that are not a list are refused', () => {
    expect(parseAdminSurfaceCapabilityDeclarations({ entry: { connections: [{ id: 'account', startParams: 'mode' }] }, at: 'surfaces[0]' }))
      .toBe('surfaces[0].connections[0].startParams must be an array of at most 8');
  });

  test('more than 8 callback fields are refused', () => {
    const callbackFields = Array.from({ length: 9 }, (_, index) => `field-${index}`);
    expect(parseAdminSurfaceCapabilityDeclarations({ entry: { connections: [{ id: 'account', callbackFields }] }, at: 'surfaces[0]' }))
      .toBe('surfaces[0].connections[0].callbackFields must be an array of at most 8');
  });

  test('a non-string start parameter name is refused, naming its index', () => {
    expect(parseAdminSurfaceCapabilityDeclarations({ entry: { connections: [{ id: 'account', startParams: ['mode', 7] }] }, at: 'surfaces[0]' }))
      .toMatch(/^surfaces\[0\]\.connections\[0\]\.startParams\[1\] must be a unique name matching /);
  });
});

const parsed = parseAdminSurfacesFile({ raw: JSON.stringify({ schemaVersion: 1, surfaces: [{ id: 'settings', title: 'Settings', entry: 'index.html' }] }) });
const descriptor = (parsed.ok ? parsed.descriptors[0] : undefined) as AdminSurfaceDescriptor;

describe('host message gate', () => {
  const frame = {};

  test('a request envelope without a payload key is not a request', () => {
    const data = { protocol: 'jini.admin-surface', version: 1, kind: 'action-request', mountId: 'm-1', requestId: 'r1', action: 'save' };
    expect(validateAdminSurfaceMessage({ event: { origin: 'null', source: frame, data }, mount: { mountId: 'm-1', frame, descriptor } }))
      .toEqual({ ok: false, ignored: 'not-an-action-request' });
  });

  test.each([[null], ['action-request'], [7]])('non-object data %j from the frame is ignored as not a request', (data) => {
    expect(validateAdminSurfaceMessage({ event: { origin: 'null', source: frame, data }, mount: { mountId: 'm-1', frame, descriptor } }))
      .toEqual({ ok: false, ignored: 'not-an-action-request' });
  });
});

describe('contribution definition', () => {
  test('is a data contribution (no plugin code runs) on the host-chosen filename', async () => {
    const definition = defineAdminSurfaceContribution({ filename: 'host-admin-surfaces.json' });
    expect(definition).toMatchObject({ filename: 'host-admin-surfaces.json', contribution: 'admin surfaces', kind: 'data' });
    expect(definition.parse({ raw: '[]' })).toEqual({ ok: false, reason: 'schemaVersion must be 1' });
    const plugin = { pluginId: 'acme-office', packageRoot: '/plugins/acme-office' };
    const importModule = async () => 'never called';
    await expect(Promise.resolve(definition.load({ plugin, descriptor, importModule }))).resolves.toEqual({ plugin, descriptor });
  });
});

describe('protocol and sandbox', () => {
  test('the init envelope has no bootstrap key when none is given', () => {
    expect(adminSurfaceInitMessage({ mountId: 'm-1' })).toStrictEqual({ protocol: 'jini.admin-surface', version: 1, kind: 'init', mountId: 'm-1' });
  });

  test('the init envelope carries the bootstrap when one is given', () => {
    const bootstrap = createAdminSurfaceBootstrap({ surfaceId: 'settings', data: { sheet: 'A' }, nowMs: 0 });
    expect(adminSurfaceInitMessage({ mountId: 'm-1' }, { bootstrap })).toEqual({ protocol: 'jini.admin-surface', version: 1, kind: 'init', mountId: 'm-1', bootstrap });
  });

  test('the init envelope carries the theme when one is given, alongside or without a bootstrap', () => {
    const theme = { scheme: 'dark', tokens: {} } as const;
    expect(adminSurfaceInitMessage({ mountId: 'm-1' }, { theme })).toStrictEqual({ protocol: 'jini.admin-surface', version: 1, kind: 'init', mountId: 'm-1', theme });
  });

  test('a file type outside the served set is labelled as opaque bytes, still nosniff, with no CORS grant', () => {
    const headers = adminSurfaceFileHeaders({ descriptor: { csp: {} }, path: 'notes.txt' });
    expect(headers['Content-Type']).toBe('application/octet-stream');
    expect(headers['X-Content-Type-Options']).toBe('nosniff');
    expect(headers).not.toHaveProperty('Access-Control-Allow-Origin');
  });
});

describe('connection status', () => {
  test('a host status without an account label reports null', async () => {
    // Malformed input on purpose: the host port is untyped at run time and may omit the field.
    const fake = createFakeSurfaceHost({ status: { accountLabel: undefined as unknown as AdminSurfaceConnectionStatus['accountLabel'] } });
    const session = openAdminSurfaceCapabilitySession(
      { capabilities: fake.port({ pluginId: 'acme-office', workspaceId: WORKSPACE_ID }), isLive: () => true, declared: { connections: [{ id: 'account', startParams: [], callbackFields: [] }] }, issued: new Set() },
      { actorId: 'admin-1' },
    );
    await expect(session.capabilities.connections.status({ connectionId: 'account' })).resolves.toMatchObject({ accountLabel: null });
  });
});

src/admin-surfaces/__tests__/descriptor..source:
/**
 * @file Unit tests for the admin-surface descriptor parser's refusals that the security suite does
 * not already pin: file-level bounds, surface and action list shapes, identity fields, duplicate
 * ids/names, and malformed CSP blocks. Each refusal names the exact field that failed.
 */
import { describe, expect, test } from 'vitest';
import { isContainedAdminSurfacePath, parseAdminSurfacesFile } from '../descriptor.js';

const SURFACE = { id: 'settings', title: 'Settings', entry: 'surfaces/settings.html' };

function parse(raw: string) {
  return parseAdminSurfacesFile({ raw });
}

function parseSurfaces(surfaces: unknown) {
  return parse(JSON.stringify({ schemaVersion: 1, surfaces }));
}

function withSurface(overrides: Record<string, unknown>) {
  return parseSurfaces([{ ...SURFACE, ...overrides }]);
}

const refused = (reason: string) => ({ ok: false, reason });

describe('file', () => {
  test('accepts a minimal surface with empty defaults', () => {
    expect(parseSurfaces([SURFACE])).toEqual({ ok: true, descriptors: [{ ...SURFACE, files: [], actions: [], csp: {} }] });
  });

  test('refuses text over 64 KiB before parsing it', () => {
    expect(parse(' '.repeat(64 * 1024 + 1))).toEqual(refused('larger than 64 KiB'));
  });

  test('refuses text that is not JSON', () => {
    expect(parse('{')).toEqual(refused('not valid JSON'));
  });

  test('refuses a top-level array', () => {
    expect(parse('[]')).toEqual(refused('schemaVersion must be 1'));
  });

  test('refuses another schema version', () => {
    expect(parse(JSON.stringify({ schemaVersion: 2, surfaces: [] }))).toEqual(refused('schemaVersion must be 1'));
  });

  test('refuses surfaces that is not an array', () => {
    expect(parseSurfaces({ settings: SURFACE })).toEqual(refused('surfaces must be an array of at most 16'));
  });

  test('refuses more than 16 surfaces', () => {
    const surfaces = Array.from({ length: 17 }, (_, index) => ({ ...SURFACE, id: `s-${index}` }));
    expect(parseSurfaces(surfaces)).toEqual(refused('surfaces must be an array of at most 16'));
  });

  test('accepts exactly 16 surfaces', () => {
    const surfaces = Array.from({ length: 16 }, (_, index) => ({ ...SURFACE, id: `s-${index}` }));
    const parsed = parseSurfaces(surfaces);
    expect(parsed.ok && parsed.descriptors.length).toBe(16);
  });

  test('refuses a surface that is not an object', () => {
    expect(parseSurfaces([SURFACE, 'settings'])).toEqual(refused('surfaces[1] must be an object'));
  });

  test('refuses a surface id declared twice', () => {
    expect(parseSurfaces([SURFACE, { ...SURFACE }])).toEqual(refused("surfaces[1].id 'settings' is declared twice"));
  });
});

describe('identity', () => {
  test.each([['Settings'], ['two--dashes'], ['-lead'], [`a${'b'.repeat(64)}`], [3]])('refuses id %j', (id) => {
    expect(withSurface({ id })).toEqual(refused('surfaces[0].id must be a lowercase hyphenated id'));
  });

  test('accepts a 64-character id', () => {
    expect(withSurface({ id: `a${'b'.repeat(63)}` }).ok).toBe(true);
  });

  test.each([[undefined], ['   '], ['t'.repeat(101)]])('refuses title %j', (title) => {
    expect(withSurface({ title })).toEqual(refused('surfaces[0].title must be a non-empty string of at most 100 characters'));
  });

  test('accepts a 100-character title', () => {
    expect(withSurface({ title: 't'.repeat(100) }).ok).toBe(true);
  });

  test('refuses an entry that is not .html', () => {
    expect(withSurface({ entry: 'surfaces/settings.htm' })).toEqual(refused('surfaces[0].entry must be a plain relative path ending in .html'));
  });
});

describe('files', () => {
  test('refuses files that is not an array', () => {
    expect(withSurface({ files: 'app.mjs' })).toEqual(refused('surfaces[0].files must be an array of at most 32'));
  });

  test('refuses more than 32 files', () => {
    expect(withSurface({ files: Array.from({ length: 33 }, (_, index) => `f${index}.js`) })).toEqual(refused('surfaces[0].files must be an array of at most 32'));
  });

  test('accepts 32 files of every allowed extension', () => {
    const files = Array.from({ length: 32 }, (_, index) => `f${index}${['.mjs', '.js', '.css', '.json'][index % 4]}`);
    expect(withSurface({ files }).ok).toBe(true);
  });

  test('names the first file with an unsupported extension', () => {
    expect(withSurface({ files: ['app.mjs', 'logo.svg'] })).toEqual(refused('surfaces[0].files[1] must be a plain relative path ending in .mjs, .js, .css, .json'));
  });
});

describe('isContainedAdminSurfacePath', () => {
  test('accepts a 200-character path', () => {
    expect(isContainedAdminSurfacePath({ value: `${'a'.repeat(196)}.mjs`, extensions: ['.mjs'] })).toBe(true);
  });

  test('refuses a 201-character path', () => {
    expect(isContainedAdminSurfacePath({ value: `${'a'.repeat(197)}.mjs`, extensions: ['.mjs'] })).toBe(false);
  });

  test('refuses a non-string', () => {
    expect(isContainedAdminSurfacePath({ value: ['a.mjs'], extensions: ['.mjs'] })).toBe(false);
  });
});

describe('actions', () => {
  const INPUT = { type: 'object' };

  test('refuses actions that is not an array', () => {
    expect(withSurface({ actions: {} })).toEqual(refused('surfaces[0].actions must be an array of at most 32'));
  });

  test('refuses more than 32 actions', () => {
    const actions = Array.from({ length: 33 }, (_, index) => ({ name: `a-${index}`, input: INPUT }));
    expect(withSurface({ actions })).toEqual(refused('surfaces[0].actions must be an array of at most 32'));
  });

  test('refuses an action that is not an object', () => {
    expect(withSurface({ actions: ['save'] })).toEqual(refused('surfaces[0].actions[0] must be an object'));
  });

  test('refuses an action name that is not an id', () => {
    expect(withSurface({ actions: [{ name: 'Save', input: INPUT }] })).toEqual(refused('surfaces[0].actions[0].name must be a lowercase hyphenated id'));
  });

  test('refuses an action name declared twice', () => {
    expect(withSurface({ actions: [{ name: 'save', input: INPUT }, { name: 'save', input: INPUT }] })).toEqual(refused("surfaces[0].actions[1].name 'save' is declared twice"));
  });

  test('names an invalid input schema', () => {
    expect(withSurface({ actions: [{ name: 'save', input: { type: 'object', pattern: 'x' } }] })).toEqual(refused("surfaces[0].actions[0].input uses unsupported keyword 'pattern'"));
  });

  test('names an invalid result schema', () => {
    expect(withSurface({ actions: [{ name: 'save', input: INPUT, result: { type: 'any' } }] })).toEqual(refused('surfaces[0].actions[0].result must declare a supported type'));
  });

  test('keeps a declared result schema', () => {
    const parsed = withSurface({ actions: [{ name: 'save', input: INPUT, result: { type: 'boolean' } }] });
    expect(parsed.ok && parsed.descriptors[0]!.actions).toEqual([{ name: 'save', effect: 'write', input: INPUT, result: { type: 'boolean' } }]);
  });
});

describe('csp', () => {
  test('refuses a csp that is not an object', () => {
    expect(withSurface({ csp: ['https://cdn.example.com'] })).toEqual(refused('surfaces[0].csp must be an object'));
  });

  test('refuses sources that are not an array', () => {
    expect(withSurface({ csp: { 'img-src': 'https://cdn.example.com' } })).toEqual(refused("surfaces[0].csp['img-src'] must be an array of at most 8"));
  });

  test('refuses more than 8 sources for one directive', () => {
    const sources = Array.from({ length: 9 }, (_, index) => `https://cdn${index}.example.com`);
    expect(withSurface({ csp: { 'img-src': sources } })).toEqual(refused("surfaces[0].csp['img-src'] must be an array of at most 8"));
  });

  test('accepts 8 bare origins on every allowed directive', () => {
    const sources = Array.from({ length: 8 }, (_, index) => `https://cdn${index}.example.com`);
    const csp = Object.fromEntries(['script-src', 'style-src', 'img-src', 'font-src', 'connect-src', 'frame-src'].map((directive) => [directive, sources]));
    expect(withSurface({ csp })).toMatchObject({ ok: true, descriptors: [{ csp }] });
  });

  test('truncates an unknown directive name to 32 characters in the refusal', () => {
    expect(withSurface({ csp: { [`x${'y'.repeat(40)}`]: [] } })).toEqual(refused(`surfaces[0].csp may not extend 'x${'y'.repeat(31)}'`));
  });
});

src/lifecycle/__tests__/unit/manifest-bo.source:
/** Boundary cases of `manifest.ts`'s field validators: each malformed field excludes exactly what it should. */
import { describe, expect, it } from 'vitest';
import { parseAgentPluginManifest, parseAgentPluginMcpConfig, readAgentPluginExtension, type McpServerConfig } from '../../manifest.js';

const PLUGIN_SCHEMA = 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json';
const MCP_SCHEMA = 'https://agent-plugins.org/schemas/1.0.0/mcp.schema.json';
const NAMESPACE = 'org.example.host';

function manifest(fields: Record<string, unknown>) {
  const parsed = parseAgentPluginManifest({ value: { $schema: PLUGIN_SCHEMA, name: 'fixture', ...fields } });
  if (!parsed.ok) throw new Error(parsed.errors.join('; '));
  return parsed.manifest;
}
/** One declared server, with optional namespaced extension metadata for it. */
function server(entry: unknown, extension?: Record<string, unknown>): McpServerConfig | undefined {
  const pluginManifest = { $schema: PLUGIN_SCHEMA, name: 'fixture', extensions: { [NAMESPACE]: { mcpServers: extension ? { one: extension } : {} } } };
  const parsed = parseAgentPluginMcpConfig({ value: { $schema: MCP_SCHEMA, mcpServers: { one: entry } }, extensionNamespace: NAMESPACE }, { pluginManifest });
  if (!parsed.ok) throw new Error(parsed.errors.join('; '));
  return parsed.config.servers.one;
}
const remote = (extension: Record<string, unknown>) => server({ type: 'streamable-http', url: 'https://example.com/mcp' }, extension);
const tokenAuth = (fields: Record<string, unknown>) => remote({ tokenAuth: { helpUrl: 'https://example.com/help', probeUrl: 'https://example.com/probe', ...fields } });

describe('plugin.json author', () => {
  it('keeps a string author', () => {
    expect(manifest({ author: 'Ada' }).author).toBe('Ada');
  });
  it('drops a non-string, non-object author', () => {
    expect(manifest({ author: 42 }).author).toBeUndefined();
  });
  it('keeps only the string members of an object author', () => {
    expect(manifest({ author: { name: 'Ada', email: 5, url: 'https://example.com' } }).author).toEqual({ name: 'Ada', url: 'https://example.com' });
  });
  it('keeps an email-only object author', () => {
    expect(manifest({ author: { email: 'ada@example.com' } }).author).toEqual({ email: 'ada@example.com' });
  });
});

describe('plugin.json shape', () => {
  it('refuses a non-object manifest', () => {
    expect(parseAgentPluginManifest({ value: [] })).toEqual({ ok: false, errors: ['plugin.json must be a JSON object'] });
  });
  // Pinned as found: the identity validator reports the same malformed extensions a second time.
  it('refuses a non-object extensions member', () => {
    const parsed = parseAgentPluginManifest({ value: { $schema: PLUGIN_SCHEMA, name: 'fixture', extensions: [] } });
    expect(parsed).toEqual({ ok: false, errors: ['plugin.json extensions must be an object', 'Plugin extensions must be an object.'] });
  });
  it('accepts a known schema without a version warning', () => {
    const parsed = parseAgentPluginManifest({ value: { $schema: PLUGIN_SCHEMA, name: 'fixture' } });
    expect(parsed.ok && parsed.warnings).toEqual(["Plugin 'fixture' has no publisher-qualified id; using 'unknown/fixture'."]);
  });
  it('omits keywords when the manifest declares none', () => {
    expect(manifest({}).keywords).toBeUndefined();
  });
});

describe('stdio servers', () => {
  it('keeps args, env and cwd when each is well formed', () => {
    expect(server({ type: 'stdio', command: 'node', args: ['a'], env: { MODE: 'x' }, cwd: '/w' }))
      .toEqual({ type: 'stdio', command: 'node', args: ['a'], env: { MODE: 'x' }, cwd: '/w' });
  });
  it('omits absent optional fields', () => {
    expect(server({ type: 'stdio', command: 'node' })).toEqual({ type: 'stdio', command: 'node' });
  });
  it('excludes an empty command', () => {
    expect(server({ type: 'stdio', command: '' })).toBeUndefined();
  });
  it('excludes non-array args', () => {
    expect(server({ type: 'stdio', command: 'node', args: 'a' })).toBeUndefined();
  });
  it('excludes args holding a non-string', () => {
    expect(server({ type: 'stdio', command: 'node', args: ['a', 1] })).toBeUndefined();
  });
  it('excludes an env with a non-string value', () => {
    expect(server({ type: 'stdio', command: 'node', env: { MODE: 1 } })).toBeUndefined();
  });
  it('excludes an env setting a reserved key', () => {
    expect(server({ type: 'stdio', command: 'node', env: { PLUGIN_ROOT: '/x' } })).toBeUndefined();
  });
  it('excludes a non-string cwd', () => {
    expect(server({ type: 'stdio', command: 'node', cwd: 1 })).toBeUndefined();
  });
});

describe('remote servers', () => {
  it('excludes an empty url', () => {
    expect(server({ type: 'sse', url: '' })).toBeUndefined();
  });
  it('excludes headers with a non-string value', () => {
    expect(server({ type: 'sse', url: 'https://example.com', headers: { A: 1 } })).toBeUndefined();
  });
  it('keeps string headers', () => {
    expect(server({ type: 'sse', url: 'https://example.com', headers: { A: 'b' } })).toEqual({ type: 'sse', url: 'https://example.com', headers: { A: 'b' } });
  });
  it('keeps authMode none', () => {
    expect(remote({ authMode: 'none' })).toEqual({ type: 'streamable-http', url: 'https://example.com/mcp', authMode: 'none' });
  });
  it('excludes an unknown authMode', () => {
    expect(remote({ authMode: 'basic' })).toBeUndefined();
  });
  it('excludes non-object defaultTools', () => {
    expect(remote({ defaultTools: ['inspect'] })).toBeUndefined();
  });
  it('excludes a default tool list over the 64-entry bound', () => {
    const names = Array.from({ length: 65 }, (_, index) => `tool${index}`);
    expect(remote({ defaultTools: { allow: names } })).toBeUndefined();
  });
  it('excludes a server entry that is not an object while still listing its id', () => {
    const parsed = parseAgentPluginMcpConfig({ value: { $schema: MCP_SCHEMA, mcpServers: { one: 'stdio' } }, extensionNamespace: NAMESPACE });
    expect(parsed).toEqual({ ok: true, config: { serverIds: ['one'], servers: {} } });
  });
});

describe('remote tokenAuth', () => {
  it('keeps importFromEnv and retiredEnv when both are valid env names', () => {
    expect(tokenAuth({ importFromEnv: 'NEW_TOKEN', retiredEnv: ['OLD_TOKEN'] }))
      .toEqual({ type: 'streamable-http', url: 'https://example.com/mcp', tokenAuth: { helpUrl: 'https://example.com/help', probeUrl: 'https://example.com/probe', importFromEnv: 'NEW_TOKEN', retiredEnv: ['OLD_TOKEN'] } });
  });
  it('excludes a non-object tokenAuth', () => {
    expect(remote({ tokenAuth: 'https://example.com' })).toBeUndefined();
  });
  it('excludes a non-https helpUrl', () => {
    expect(tokenAuth({ helpUrl: 'http://example.com/help' })).toBeUndefined();
  });
  it('excludes an unparseable probeUrl', () => {
    expect(tokenAuth({ probeUrl: 'not a url' })).toBeUndefined();
  });
  it('excludes a non-string helpUrl', () => {
    expect(tokenAuth({ helpUrl: 7 })).toBeUndefined();
  });
  it('excludes a helpUrl over 2048 characters', () => {
    expect(tokenAuth({ helpUrl: `https://example.com/${'a'.repeat(2048)}` })).toBeUndefined();
  });
  it('excludes a lower-case importFromEnv', () => {
    expect(tokenAuth({ importFromEnv: 'token' })).toBeUndefined();
  });
  it('excludes retiredEnv holding an invalid name', () => {
    expect(tokenAuth({ retiredEnv: ['OK', 'bad-name'] })).toBeUndefined();
  });
  it('excludes retiredEnv over the 32-entry bound', () => {
    expect(tokenAuth({ retiredEnv: Array.from({ length: 33 }, (_, index) => `OLD_${index}`) })).toBeUndefined();
  });
});

describe('extension namespaces', () => {
  it('parseAgentPluginMcpConfig refuses a blank namespace', () => {
    expect(() => parseAgentPluginMcpConfig({ value: {}, extensionNamespace: ' ' })).toThrow('An extension namespace is required');
  });
  it('readAgentPluginExtension ignores a namespace whose value is not an object', () => {
    expect(readAgentPluginExtension({ manifest: { extensions: { [NAMESPACE]: 'x' } }, namespace: NAMESPACE, read: () => 'read' })).toBeUndefined();
  });
});

src/admin-surfaces/__tests__/admin-surfa.source:
/**
 * @file The one phase-A vertical-slice proof for admin surfaces: a neutral fixture plugin on disk
 * declares a surface in a HOST-NAMED contribution file; the real contribution loader and trusted file
 * reader admit it; the host serves its entry with the strict headers, mounts it, posts init with a
 * bootstrap, and a surface client round-trips one declared action through the host-page gate and the
 * server dispatcher to a host handler, then asks the host page to open one declared https link
 * through the host's opener port (and is refused an undeclared one). Windows are simulated with structured-clone message passing
 * that, like a browser, drops a message whose target origin does not match the receiver.
 */
import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, expect, test } from 'vitest';
import { createPluginContributionLoader } from '../../lifecycle/contribution-loader.js';
import { readTrustedPluginFile } from '../../lifecycle/__tests__/test-support.js';
import {
  adminSurfaceActionResponse, adminSurfaceInitMessage, createAdminSurfaceActionDispatcher, createAdminSurfaceBootstrap,
  createAdminSurfaceMount, defineAdminSurfaceContribution, openAdminSurfaceLink, readAdminSurfaceFile, validateAdminSurfaceMessage,
} from '../index.js';
import { createAdminSurfaceClient, type AdminSurfaceIncomingMessage } from '../surface-client.js';

const HOST_ORIGIN = 'https://admin.example.com';
const FILENAME = 'acme-admin-surfaces.json';
let root: string | undefined;
afterEach(async () => { if (root) await rm(root, { recursive: true, force: true }); root = undefined; });

/** A window that delivers posted messages to its listeners, dropping any whose target origin is not its own. */
function simulatedWindow(ownOrigin: string) {
  const listeners = new Set<(event: AdminSurfaceIncomingMessage) => void>();
  return {
    listen: (handler: (event: AdminSurfaceIncomingMessage) => void) => { listeners.add(handler); return () => { listeners.delete(handler); }; },
    deliver(required: { readonly data: unknown; readonly targetOrigin: string; readonly origin: string; readonly source: unknown }) {
      if (required.targetOrigin !== '*' && required.targetOrigin !== ownOrigin) return;
      for (const listener of listeners) listener({ origin: required.origin, source: required.source, data: structuredClone(required.data) });
    },
  };
}

test('a fixture plugin surface loads, is served strictly, mounts and round-trips one declared action', async () => {
  root = await mkdtemp(path.join(tmpdir(), 'admin-surface-slice-'));
  await mkdir(path.join(root, 'surface'));
  await writeFile(path.join(root, FILENAME), JSON.stringify({
    schemaVersion: 1,
    surfaces: [{
      id: 'connection-settings', title: 'Connection settings', entry: 'surface/index.html', files: ['surface/app.mjs'],
      actions: [{ name: 'save-selection', input: { type: 'object', properties: { resourceId: { type: 'string', maxLength: 128 } }, required: ['resourceId'] },
        result: { type: 'object', properties: { saved: { type: 'boolean' } }, required: ['saved'] } }],
      csp: { 'connect-src': ['https://api.example.com'] },
      linkOrigins: ['https://accounts.example.com'],
    }],
  }));
  await writeFile(path.join(root, 'surface/index.html'), '<!doctype html><script type="module" src="app.mjs"></script>');
  await writeFile(path.join(root, 'surface/app.mjs'), 'export {};');
  const plugin = { pluginId: 'acme-office', packageRoot: root };

  const loader = createPluginContributionLoader({
    findPackages: async () => [{ trusted: plugin }],
    readFile: ({ plugin: trusted, filename }) => readTrustedPluginFile(trusted, filename),
    importModule: async () => 'surfaces never import code',
  });
  const loaded = await loader.loadPluginContributions({ workspaceId: 'w1', definition: defineAdminSurfaceContribution({ filename: FILENAME }) });
  expect(loaded.refusals).toEqual([]);
  const surface = loaded.items[0]!;

  const served = await readAdminSurfaceFile({ surface, path: surface.descriptor.entry, readFile: ({ plugin: trusted, filename }) => readTrustedPluginFile(trusted, filename) });
  expect(served).toMatchObject({ ok: true, body: '<!doctype html><script type="module" src="app.mjs"></script>', headers: { 'Content-Type': 'text/html; charset=utf-8' } });
  expect(served.ok && served.headers['Content-Security-Policy']).toContain('connect-src https://api.example.com; frame-src');

  const handled: unknown[] = [];
  const { dispatch } = createAdminSurfaceActionDispatcher<{ readonly workspaceId: string }>({
    descriptor: surface.descriptor,
    handlers: { 'save-selection': async ({ payload, context }) => { handled.push({ payload, context }); return { saved: true }; } },
  });
  const mount = createAdminSurfaceMount({ surfaceId: surface.descriptor.id });
  const hostWindow = simulatedWindow(HOST_ORIGIN);
  const frameWindow = simulatedWindow('null');
  const frameRecord = { mountId: mount.mountId, frame: frameWindow, descriptor: surface.descriptor };

  // How the frame sees its parent: posting to it lands in the host window as a message from the frame.
  const parentPort = { postMessage: (data: unknown, targetOrigin: string) => hostWindow.deliver({ data, targetOrigin, origin: 'null', source: frameWindow }) };
  const serverRoundTrips: Promise<void>[] = [];
  const opened: string[] = [];
  hostWindow.listen((event) => {
    serverRoundTrips.push(openAdminSurfaceLink({ event, mount: frameRecord, openLink: ({ url }) => { opened.push(url); } }).then((link) => {
      if ('response' in link) frameWindow.deliver({ data: link.response, targetOrigin: '*', origin: HOST_ORIGIN, source: parentPort });
    }));
    const verdict = validateAdminSurfaceMessage({ event, mount: frameRecord });
    if (!verdict.ok) return;
    // The host page forwards to its server route as JSON; the server, not the frame, supplies context.
    const body = JSON.parse(JSON.stringify({ action: verdict.request.action, payload: verdict.request.payload }));
    serverRoundTrips.push(dispatch({ ...body, context: { workspaceId: 'w1' } }).then((outcome) => {
      frameWindow.deliver({ data: adminSurfaceActionResponse({ request: verdict.request, outcome }), targetOrigin: '*', origin: HOST_ORIGIN, source: parentPort });
    }));
  });

  const client = createAdminSurfaceClient({ parent: parentPort, listen: frameWindow.listen }, { nowMs: () => 2_000 });

  const bootstrap = createAdminSurfaceBootstrap({ surfaceId: surface.descriptor.id, data: { mode: 'pick' }, nowMs: 1_000 });
  frameWindow.deliver({ data: adminSurfaceInitMessage({ mountId: mount.mountId }, { bootstrap }), targetOrigin: '*', origin: HOST_ORIGIN, source: parentPort });
  await client.ready;
  expect(client.bootstrap()).toEqual({ mode: 'pick' });

  const result = client.call({ action: 'save-selection', payload: { resourceId: 'res-1' } });
  await Promise.resolve();
  await Promise.all(serverRoundTrips);
  await expect(result).resolves.toEqual({ saved: true });
  expect(handled).toEqual([{ payload: { resourceId: 'res-1' }, context: { workspaceId: 'w1' } }]);

  const link = client.openLink({ url: 'https://accounts.example.com/permissions' });
  await Promise.resolve();
  await Promise.all(serverRoundTrips);
  await expect(link).resolves.toBeUndefined();
  const undeclared = client.openLink({ url: 'https://elsewhere.example.net/' });
  await Promise.resolve();
  await Promise.all(serverRoundTrips);
  await expect(undeclared).rejects.toMatchObject({ name: 'AdminSurfaceCallError', code: 'link-undeclared', retryable: false });
  expect(opened).toEqual(['https://accounts.example.com/permissions']);
  client.close();
});

src/admin-surfaces/__tests__/delivery-bi.source:
/**
 * @file Unit tests for the admin-surface `deliveryBindings` port's shapes and bounds: what the host
 * receives on save (a checked copy with only the known fields), what the plugin gets back (the port's
 * shape, never the host's connection ref), updating and removing the surface's own bindings, and the
 * refusals for a malformed draft (enabled flag, form ids, config) or an unknown binding id. The host is the shared
 * typed fake; no network.
 */
import { describe, expect, test } from 'vitest';
import { WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import type { AdminSurfaceCapabilityDeclarations } from '../capability-declarations.js';
import type { AdminSurfaceDeliveryBinding, AdminSurfaceDeliveryBindingDraft } from '../delivery-bindings.js';
import { openAdminSurfaceCapabilitySession } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const DECLARED: AdminSurfaceCapabilityDeclarations = { connections: [{ id: 'account', startParams: [], callbackFields: [] }], deliveryAdapters: ['acme-rows', 'acme-notes'] };
const OURS: AdminSurfaceDeliveryBinding = { bindingId: 'ours-1', adapterId: 'acme-rows', connectionId: 'account', enabled: false, formIds: ['contact'], config: { tab: 7 } };
const DRAFT: AdminSurfaceDeliveryBindingDraft = { adapterId: 'acme-rows', connectionId: 'account', enabled: true, formIds: ['contact'], config: { tab: 1 } };

function open() {
  const fake = createFakeSurfaceHost({ bindings: [OURS] });
  const session = openAdminSurfaceCapabilitySession(
    { capabilities: fake.port({ pluginId: 'acme-office', workspaceId: WORKSPACE_ID }), isLive: () => true, declared: DECLARED, issued: new Set() },
    { actorId: 'admin-1' },
  );
  return { ...fake, port: session.capabilities.deliveryBindings! };
}

describe('save', () => {
  test('a new binding reaches the host as a checked copy with only the known fields', async () => {
    const session = open();
    // Malformed on purpose: a draft carrying a host field must not pass it on.
    await session.port.save({ ...DRAFT, connectionRef: 'ref-from-plugin' } as AdminSurfaceDeliveryBindingDraft);
    expect(session.log.calls).toEqual(['acme-office:bindings.save:{"adapterId":"acme-rows","connectionId":"account","enabled":true,"formIds":["contact"],"config":{"tab":1}}']);
  });
  test('the saved binding comes back in the port shape, without the host\'s connection ref', async () => {
    await expect(open().port.save({ ...DRAFT, formIds: [] })).resolves.toStrictEqual({ bindingId: 'binding-2', adapterId: 'acme-rows', connectionId: 'account', enabled: true, formIds: [], config: { tab: 1 } });
  });
  test('the stored config is a copy the plugin cannot change afterwards', async () => {
    const session = open();
    const config = { tab: 1 };
    await session.port.save({ ...DRAFT, config });
    config.tab = 2;
    expect(session.bindings.get('binding-2')?.config).toStrictEqual({ tab: 1 });
  });
  test('the stored form ids are a copy the plugin cannot change afterwards', async () => {
    const session = open();
    const formIds = ['contact'];
    await session.port.save({ ...DRAFT, formIds });
    formIds.push('quote');
    expect(session.bindings.get('binding-2')?.formIds).toStrictEqual(['contact']);
  });
  test('the surface\'s own binding is updated in place through its id', async () => {
    const session = open();
    await expect(session.port.save({ ...DRAFT, bindingId: 'ours-1', adapterId: 'acme-notes', formIds: ['contact', 'quote'] }))
      .resolves.toStrictEqual({ bindingId: 'ours-1', adapterId: 'acme-notes', connectionId: 'account', enabled: true, formIds: ['contact', 'quote'], config: { tab: 1 } });
    expect(session.bindings.size).toBe(1);
  });
  test('64 form ids are accepted', async () => {
    const formIds = Array.from({ length: 64 }, (_, index) => `form-${index}`);
    await expect(open().port.save({ ...DRAFT, formIds })).resolves.toMatchObject({ formIds });
  });
  test('a config of exactly the size limit is accepted', async () => {
    const config = { pad: 'x'.repeat(16 * 1024 - '{"pad":""}'.length) };
    await expect(open().port.save({ ...DRAFT, config })).resolves.toMatchObject({ bindingId: 'binding-2' });
  });

  // Malformed drafts on purpose (a plugin is JavaScript): each is refused before the host sees it.
  test.each([
    ['not an object', null, 'A delivery binding must be an object.'],
    ['a non-boolean enabled flag', { ...DRAFT, enabled: 'yes' }, 'A delivery binding needs enabled: true or false.'],
    ['form ids that are not an array', { ...DRAFT, formIds: 'contact' }, 'formIds must be at most 64 unique short form ids.'],
    ['65 form ids', { ...DRAFT, formIds: Array.from({ length: 65 }, (_, index) => `form-${index}`) }, 'formIds must be at most 64 unique short form ids.'],
    ['a form id outside the short-id shape', { ...DRAFT, formIds: ['contact', 'a b'] }, 'formIds must be at most 64 unique short form ids.'],
    ['a form id listed twice', { ...DRAFT, formIds: ['contact', 'contact'] }, 'formIds must be at most 64 unique short form ids.'],
    ['a config that is an array', { ...DRAFT, config: [1] }, "A delivery binding's config must be a JSON object."],
    ['a config that is missing', { ...DRAFT, config: undefined }, "A delivery binding's config must be a JSON object."],
    ['a config that is not plain JSON', { ...DRAFT, config: { at: new Date(0) } }, 'A settings value must be plain JSON data'],
  ])('a draft with %s is refused', async (_label, draft, message) => {
    const session = open();
    await expect(session.port.save(draft as unknown as AdminSurfaceDeliveryBindingDraft)).rejects.toThrow(message);
    expect(session.log.calls).toEqual([]);
  });
  test('an undeclared adapter id is cut to 64 characters in the refusal', async () => {
    const long = `x${'y'.repeat(99)}`;
    await expect(open().port.save({ ...DRAFT, adapterId: long })).rejects.toThrow(`This admin surface does not declare delivery adapter '${long.slice(0, 64)}', so`);
  });
  test('an unknown binding id is refused', async () => {
    await expect(open().port.save({ ...DRAFT, bindingId: 'missing' })).rejects.toThrow("No delivery binding 'missing' belongs to this surface's delivery adapters; list the bindings and retry.");
  });
});

describe('list and remove', () => {
  test('a binding the host lists for every form comes back as allForms: true, without a formIds key', async () => {
    const session = open();
    const { formIds: _formIds, ...rest } = OURS as AdminSurfaceDeliveryBinding & { formIds: readonly string[] };
    const everyForm: AdminSurfaceDeliveryBinding = { ...rest, allForms: true };
    session.bindings.set('ours-1', everyForm);
    await expect(session.port.list()).resolves.toStrictEqual([everyForm]);
  });
  test('a listed binding with form ids comes back with a copy of them', async () => {
    const session = open();
    const [listed] = await session.port.list();
    expect([listed, listed?.formIds === session.bindings.get('ours-1')?.formIds]).toStrictEqual([OURS, false]);
  });
  test('the surface\'s own binding is removed through its id', async () => {
    const session = open();
    await expect(session.port.remove({ bindingId: 'ours-1' })).resolves.toBeUndefined();
    expect(session.bindings.size).toBe(0);
    expect(session.log.calls).toEqual(['acme-office:bindings.list:{}', 'acme-office:bindings.remove:{"bindingId":"ours-1"}']);
  });
  test('removing an unknown binding id is refused', async () => {
    await expect(open().port.remove({ bindingId: 'missing' })).rejects.toThrow("No delivery binding 'missing' belongs to this surface's delivery adapters; list the bindings and retry.");
  });
});

