import { withFileLock } from "@jini-ai/platform/fs/file-lock";
import * as nativeFilesystem from "node:fs/promises";
import { test, expect } from 'vitest';
import { validatePluginManifest, validateMcpManifest, isPluginManifest, isMcpManifest } from '../index.js';
import { createAgentPluginLifecycle, createAgentPluginLayout, parseAgentPluginManifest, fetchAgentPluginArchive } from '../lifecycle/index.js';
import { createNodeAgentPluginEffects } from '../lifecycle/node.js';
import { ports } from '../lifecycle/__tests__/test-support.js';
import { mkdtemp } from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { forceRemove } from '../lifecycle/__tests__/fixtures/force-remove.js';

test('object validators preserve legacy structural validation', () => {
  for (const value of [null, [], {}, { name: '' }, { name: 'toolkit' }]) {
    expect(validatePluginManifest({ value })).toBe(isPluginManifest(value));
    expect(validateMcpManifest({ value })).toBe(isMcpManifest(value));
  }
  expect(validateMcpManifest({ value: { mcpServers: {} } })).toBe(true);
});

test('identity namespace injection preserves the legacy plugin format and selects host metadata', () => {
  const value = {
    $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'toolkit',
    extensions: {
      tovu: { id: 'legacy/toolkit', provides: ['source-control'] },
      example: { id: 'example/toolkit', provides: ['deploy-target:fly'] },
    },
  };
  expect(parseAgentPluginManifest({ value })).toMatchObject({
    ok: true, manifest: { id: 'legacy/toolkit', provides: ['source-control'] }, warnings: [],
  });
  expect(parseAgentPluginManifest({ value }, { identityNamespace: 'example' })).toMatchObject({
    ok: true, manifest: { id: 'example/toolkit', provides: ['deploy-target:fly'] }, warnings: [],
  });
  const invalid = { ...value, extensions: { ...value.extensions, example: { id: 'invalid' } } };
  expect(validatePluginManifest({ value: invalid })).toBe(true);
  expect(validatePluginManifest({ value: invalid }, { identityNamespace: 'example' })).toBe(false);
  expect(parseAgentPluginManifest({ value: invalid }, { identityNamespace: 'example' })).toEqual({
    ok: false, errors: ['Plugin id must have the form publisher/name (lowercase letters, digits, dots and hyphens).'],
  });
});

test('strict parser preserves standard author objects and legacy author strings', () => {
  const author = { name: 'Example', email: 'author@example.com', url: 'https://example.com' };
  for (const value of [author, 'Example']) {
    const result = parseAgentPluginManifest({ value: {
      $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'toolkit', author: value,
    } });
    expect(result).toMatchObject({ ok: true, manifest: { author: value } });
  }
});

// REGRESSION: fails if lifecycle calls fs/promises.open with a wrapped path object.
test('archive installation accepts native filesystem effects through the public facade', async () => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'plugin-contract-'));
  const effects = createNodeAgentPluginEffects({});
  const seen: string[] = [];
  const api = createAgentPluginLifecycle({ ...ports, ...effects,
    layout: createAgentPluginLayout({ root }),
    filesystem: { ...effects.filesystem, open: async (...args: Parameters<typeof nativeFilesystem.open>) => {
      expect(typeof args[0]).toBe('string');
      seen.push(String(args[0]));
      return effects.filesystem.open(...args);
    } },
  });
  try {
    const sourceDir = path.join(root, 'source');
    await effects.filesystem.mkdir(sourceDir, { recursive: true });
    const handle = await effects.filesystem.open(path.join(sourceDir, 'plugin.json'), 'w');
    await handle.writeFile(JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'toolkit' }), 'utf8');
    await handle.close();
    const packed = await api.packAgentPluginDirectory({ sourceDir });
    const reader = api.createBundledSourceArchiveReader({});
    const installed = await api.installAgentPlugin({ archive: packed.bytes, expectedSha256: packed.sha256,
      archiveReader: { entries: required => { expect(required.archive).toBe(packed.bytes); return reader.entries(required); } },
      layout: createAgentPluginLayout({ root }),
      workspaceId: 'example',
    });
    expect(installed.pluginId).toBe('toolkit');
    expect(installed.files).toEqual(['plugin.json']);
    expect(seen.some(p => p.endsWith('plugin.json'))).toBe(true);
  } finally { await forceRemove(root); }
});

test('download passes URL and redirect policy as separate objects to the fetch port', async () => {
  const requests: unknown[] = [];
  const result = await fetchAgentPluginArchive({ url: 'https://example.com/plugin.zip',
    outboundGuard: { assertAllowed: async () => {} },
    fetch: async (required, optional) => { requests.push([required, optional]); return new Response(new Uint8Array([4, 5])); },
  });
  expect(requests).toEqual([[{ url: 'https://example.com/plugin.zip' }, { redirect: 'manual' }]]);
  expect(Array.from(result.archive)).toEqual([4, 5]);
});

test('public callbacks receive objects, including lock ownership checks', async () => {
  const api = createAgentPluginLifecycle(ports);
  const received: unknown[] = [];
  const items = [{ id: 'plugin-a' }];
  expect(api.filterActiveAgentPlugins({ activations: { schemaVersion: 1, plugins: {} }, items,
    pluginIdOf: required => { received.push(required); return required.item.id; },
  })).toEqual(items);
  expect(received).toEqual([{ item: items[0] }]);
  const root = await mkdtemp(path.join(os.tmpdir(), 'plugin-lock-contract-'));
  try {
    const result = await withFileLock({ lockPath: path.join(root, 'lock'),
      run: async lock => { await lock.assertHeld({}); return lock.lockPath; },
    });
    expect(api).not.toHaveProperty('withExclusiveFileLock');
    expect(result).toBe(path.join(root, 'lock'));
  } finally { await forceRemove(root); }
});

src/lifecycle/tools/__tests__/agent-plug.source:
/**
 * @file Security pins (phase A) for the read-only plugin state an executable tool receives: the tool
 * port carries `get` only (never `set` or `delete`, even when the host hands over its full store), keys
 * pass the same shape check as the admin-surface state, the plugin cannot choose another plugin's or
 * workspace's keys (the projection scopes the host port by the calling plugin and workspace, and the
 * host receives the key alone), and a reader the module kept is revoked once the plugin is disabled.
 */
import { expect, test } from 'vitest';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';
import { createFakeSurfaceHost } from '../../../admin-surfaces/__tests__/surface-support.js';
import { openCapabilitySession, REVOKED_MESSAGE, type AgentPluginToolCapabilities, type AgentPluginToolCapabilityScope, createIssuedTokenMemories } from '../capabilities.js';
import type { LoadedAgentPluginTool } from '../definition.js';
import { createAgentPluginToolProjection } from '../projection.js';
import { fakeCapabilities, WORKSPACE_ID } from './support.js';

const KEY_MESSAGE = 'A settings key must be a short name of at most 128 characters.';
const SCHEMA = { type: 'object', additionalProperties: false, properties: {} };

/** Tool capabilities over the shared fake host: its full state store (get, set, delete) is what the host passes. */
function toolPort(fake: ReturnType<typeof createFakeSurfaceHost>) {
  return (scope: AgentPluginToolCapabilityScope): AgentPluginToolCapabilities => ({ ...fakeCapabilities(fake.log), state: fake.port(scope).state });
}

function session(state: AgentPluginToolCapabilities['state'], live: () => boolean = () => true) {
  return openCapabilitySession({ capabilities: { ...fakeCapabilities({ tokenRequests: [], requests: [] }), state }, isLive: live, issued: new Set() });
}

test('a tool\'s state port has get only, frozen, even when the host passes its full store', () => {
  const fake = createFakeSurfaceHost();
  const { state } = openCapabilitySession({ capabilities: toolPort(fake)({ pluginId: 'acme-office', workspaceId: WORKSPACE_ID }), isLive: () => true, issued: new Set() }).capabilities;
  expect(Object.keys(state)).toEqual(['get']);
  expect(Object.isFrozen(state)).toBe(true);
  expect('set' in state || 'delete' in state).toBe(false);
});

test.each(['', '../x', 'a b', 'k'.repeat(129), 7])('a tool state key %j outside the short-name shape is refused before the host sees it', async (key) => {
  const seen: unknown[] = [];
  const { capabilities } = session({ get: async (input) => { seen.push(input); return null; } });
  await expect(capabilities.state.get({ key: key as string })).rejects.toThrow(KEY_MESSAGE);
  expect(seen).toEqual([]);
});

test('the host receives the key alone: a plugin cannot name another plugin or workspace', async () => {
  const seen: unknown[] = [];
  const { capabilities } = session({ get: async (input, optional) => { seen.push([input, optional]); return 'v'; } });
  // Malformed input on purpose: extra scope fields a plugin might try to smuggle in.
  expect(await capabilities.state.get({ key: 'products', pluginId: 'other', workspaceId: 'w2' } as never, { pluginId: 'other' } as never)).toBe('v');
  expect(seen).toStrictEqual([[{ key: 'products' }, undefined]]);
});

const reader = (pluginId: string): LoadedAgentPluginTool => ({
  pluginId, descriptor: { name: 'flags', description: 'Read flags.', effect: 'read', module: 'tools/flags.mjs', inputSchema: SCHEMA },
  module: { invoke: async ({ capabilities }) => ({ products: await capabilities.state.get({ key: 'products' }) }) },
});

function projected(fake: ReturnType<typeof createFakeSurfaceHost>, loaded: readonly LoadedAgentPluginTool[]) {
  const registry = createPluginContributionRegistry({});
  const projection = createAgentPluginToolProjection({ issuedTokens: createIssuedTokenMemories(), registry, toolIdFor: pluginToolIdFor, capabilities: toolPort(fake) });
  projection.sync({ loaded, refusals: [] });
  const call = (pluginId: string, workspaceId: string) => {
    const snapshot = registry.list({}).find((candidate) => candidate.pluginId === pluginId)!;
    return snapshot.tools[0]!.handler({ pluginId, sdk: snapshot.sdk, auth: { access: 'member', workspaceId }, input: {} });
  };
  return { projection, call };
}

test('a tool reads only its own plugin\'s state in its own workspace', async () => {
  const fake = createFakeSurfaceHost();
  await fake.port({ pluginId: 'plugin-a', workspaceId: WORKSPACE_ID }).state.set({ key: 'products', value: { tables: true } });
  const { call } = projected(fake, [reader('plugin-a'), reader('plugin-b')]);
  expect(await call('plugin-a', WORKSPACE_ID)).toEqual({ products: { tables: true } });
  expect(await call('plugin-b', WORKSPACE_ID)).toEqual({ products: null });
  expect(await call('plugin-a', 'workspace-other')).toEqual({ products: null });
});

test('a state reader the module kept is revoked once the plugin is disabled', async () => {
  const fake = createFakeSurfaceHost();
  let kept: AgentPluginToolCapabilities['state'] | undefined;
  const keeper: LoadedAgentPluginTool = { ...reader('plugin-a'), module: { invoke: ({ capabilities }) => { kept = capabilities.state; return 'ok'; } } };
  const { projection, call } = projected(fake, [keeper]);
  expect(await call('plugin-a', WORKSPACE_ID)).toBe('ok');
  projection.sync({ loaded: [], refusals: [] });
  await expect(kept!.get({ key: 'products' })).rejects.toThrow(REVOKED_MESSAGE);
});

