import { test, expect } from 'vitest';
import { mkdtemp } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { createAgentPluginLifecycle, createAgentPluginLayout, type AgentPluginArchiveReaderPort } from '../../index.js';
import { ports } from '../test-support.js';
import { createInstalledPackageIndex } from '../../installed-package-index.js';
import { forceRemove } from '../fixtures/force-remove.js';

// Replaces the consumer's opt-in real-site proof with an isolated, real on-disk installation.
test('a real install injects exact skill markdown and refuses an absent pinned ref', async () => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'plugin-real-install-'));
  const layout = createAgentPluginLayout({ root });
  const api = createAgentPluginLifecycle({ ...ports, layout });
  const markdown = '# Interface design\n\nRead the actual installed bytes.\n';
  const archive = Buffer.from('source-archive');
  const files = {
    'plugin.json': JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'interface-design' }),
    'skills/interface-design/SKILL.md': markdown,
    'skills/interface-design/references/foundations.md': 'A stable visual foundation precedes individual screens.\n',
    'skills/interface-design/examples/card.tsx': 'export const Card = () => <section />;\n',
    'skills/interface-design/resources/image.png': 'NOT_READABLE_TEXT',
    'skills/other-skill/SKILL.md': '# Other skill\n',
  };
  const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
    for (const [entryPath, text] of Object.entries(files)) yield { kind: 'file', entryPath, declaredSize: Buffer.byteLength(text), openReadStream: async function* () { yield Buffer.from(text); } };
  } };
  try {
    const installed = await api.installAgentPlugin({ archive, archiveReader, expectedSha256: createHash('sha256').update(archive).digest('hex'), layout, workspaceId: 'workspace-a' });
    const workspaceLayout = layout.forWorkspace({ workspaceId: 'workspace-a' });
    const index = createInstalledPackageIndex({ ports: { ...ports, layout } });
    expect(await index.indexInstalledRoot({ packageRoot: installed.packageRoot, archiveDigest: installed.archiveDigest })).toEqual(installed);
    expect(await api.listInstalledPlugins({ workspaceRoot: workspaceLayout.root })).toEqual([installed]);
    const result = await api.resolveAgentPluginRefs({ pluginRefIds: ['interface-design'], workspaceLayout });
    expect(result.ok).toBe(true);
    if (!result.ok) throw new Error(result.reason);
    expect(result.promptPrefix).toContain(markdown);
    expect(result.promptPrefix).toContain('files: ["examples/card.tsx","references/foundations.md"]');
    expect(result.promptPrefix).toContain("skill 'interface-design' and file '<relative path>'");
    expect(result.promptPrefix).not.toContain(installed.packageRoot);
    expect(result.promptPrefix).not.toContain(root);
    expect(result.promptPrefix).not.toContain('NOT_READABLE_TEXT');
    expect(result.promptPrefix).not.toContain('# Other skill');
    const reference = await api.readInstalledSkillFile({ packageRoot: installed.packageRoot, skillPath: 'skills/interface-design/SKILL.md' }, { file: 'references/foundations.md' });
    expect(reference).toEqual({ text: 'A stable visual foundation precedes individual screens.\n', files: ['examples/card.tsx', 'references/foundations.md'] });
    const sibling = await api.readInstalledSkillFile({ packageRoot: installed.packageRoot, skillPath: 'skills/interface-design/SKILL.md' }, { file: '../other-skill/SKILL.md' });
    expect(sibling.text).toBe('');
    expect(sibling.note).toContain('File request refused:');
    expect(sibling.files).toEqual(reference.files);
    expect(JSON.stringify(sibling)).not.toContain(installed.packageRoot);
    const pointerApi = createAgentPluginLifecycle({ ...ports, layout, deliveryMode: 'pointer', formatPluginToolPointer: ({ pluginId }) => `host_read_plugin({"id":"${pluginId}"})` });
    const pointer = await pointerApi.resolveAgentPluginRefs({ pluginRefIds: ['interface-design'], workspaceLayout });
    expect(pointer.ok).toBe(true);
    if (pointer.ok) {
      expect(pointer.promptPrefix).toContain('host_read_plugin({"id":"interface-design"})');
      expect(pointer.promptPrefix).not.toContain(markdown);
    }
    const override = await pointerApi.resolveAgentPluginRefs({ pluginRefIds: ['interface-design'], workspaceLayout }, { deliveryMode: 'inject' });
    if (!override.ok) throw new Error(override.reason);
    expect(override.promptPrefix).toContain(markdown);
    const absent = await api.resolveAgentPluginRefs({ pluginRefIds: ['not-installed'], workspaceLayout });
    expect(absent.ok).toBe(false);
    if (!absent.ok) expect(absent.reason).toContain('not-installed');
  } finally { await forceRemove(root); }
});

src/lifecycle/__tests__/integration/agen.source:
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "../legacy-test.js";

import { forceRemove } from "../fixtures/force-remove.js";
import { readInstalledSkillMarkdown } from "../test-support.js";

import { installAgentPlugin } from "../test-support.js";
import { type AgentPluginArchiveEntry, type AgentPluginArchiveReaderPort } from "../../install.js";
import { resolveAgentPluginLayout } from "../test-support.js";

import { parseAgentPluginMcpConfig } from "../test-support.js";


/**
 * @file End-to-end proof that layout + install + manifest + capability-projection compose into one
 * coherent slice, not four units that only pass in isolation. Mirrors a real caller's own sequence:
 * resolve where bytes go, extract+verify an archive, parse its optional `mcp.json`, and read the
 * installed files back through the same containment guarantee — no step here reaches around another
 * (no direct disk reads bypassing `package-paths.ts`'s containment check, no hand-built
 * `InstalledAgentPlugin` fixture).
 */

function fileEntry(entryPath: string, content: string): AgentPluginArchiveEntry {
  const bytes = Buffer.from(content, "utf8");
  return {
    kind: "file",
    entryPath,
    declaredSize: bytes.byteLength,
    executable: false,
    async *openReadStream() {
      yield bytes;
    },
  };
}

function reader(entries: readonly AgentPluginArchiveEntry[]): AgentPluginArchiveReaderPort {
  return {
    async *entries() {
      yield* entries;
    },
  };
}

test("install -> parse mcp.json -> read installed files through the containment guarantee, end to end, for a plugin with both a skill and an MCP server", async () => {
  const cwd = await mkdtemp(path.join(tmpdir(), "host-agent-plugin-pipeline-test-"));
  try {
    const instanceLayout = resolveAgentPluginLayout({ cwd, env: {} });
    const workspaceId = "11111111-1111-4111-8111-111111111111";

    const manifest = JSON.stringify({
      $schema: "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
      name: "ui-ux-design",
      version: "1.1.0",
      description: "AI Dev Shop UI/UX and interface design guidance.",
    });
    const mcpConfig = JSON.stringify({
      $schema: "https://agent-plugins.org/schemas/1.0.0/mcp.schema.json",
      mcpServers: { main: { type: "stdio", command: "./server/index.js" } },
    });
    const skillMarkdown = "# UI/UX Design\n\nGuidance for interface work.";

    const archive = new Uint8Array(Buffer.from("integration-fixture-archive"));
    const digest = createHash("sha256").update(archive).digest("hex");

    const installed = await installAgentPlugin({
      archive,
      expectedSha256: digest,
      archiveReader: reader([
        fileEntry("plugin.json", manifest),
        fileEntry("mcp.json", mcpConfig),
        fileEntry("skills/ui-ux-design/SKILL.md", skillMarkdown),
      ]),
      layout: instanceLayout,
      workspaceId,
    });

    assert.equal(installed.pluginId, "ui-ux-design");

    // A real caller reads mcp.json THROUGH the same containment guarantee installed skills use —
    // proving `readInstalledSkillMarkdown`'s containment primitive generalizes to any installed file,
    // not only the one path shape its own unit tests exercise.
    const mcpConfigRaw = await readInstalledSkillMarkdown(installed.packageRoot, "mcp.json");
    const parsedMcp = parseAgentPluginMcpConfig(JSON.parse(mcpConfigRaw));
    assert.equal(parsedMcp.ok, true);
    const mcpServerIds = parsedMcp.ok ? parsedMcp.config.serverIds : [];
    assert.deepEqual(mcpServerIds, ["main"]);

    // The same primitive reads a skill's authored markdown back byte-for-byte, at its real
    // package-relative path.
    const readBackSkill = await readInstalledSkillMarkdown(installed.packageRoot, "skills/ui-ux-design/SKILL.md");
    assert.equal(readBackSkill, skillMarkdown);

    // Re-installing the SAME archive bytes (as a second workspace "installing" the same plugin@version
    // would) still deduplicates publication — Layout B stages again to identify the plugin before
    // choosing its content-addressed directory. The installed root and contents stay unchanged.
    const secondInstall = await installAgentPlugin({
      archive,
      expectedSha256: digest,
      archiveReader: reader([
        fileEntry("plugin.json", manifest),
        fileEntry("mcp.json", mcpConfig),
        fileEntry("skills/ui-ux-design/SKILL.md", skillMarkdown),
      ]),
      layout: instanceLayout,
      workspaceId,
    });
    assert.equal(secondInstall.packageRoot, installed.packageRoot);
    assert.deepEqual(secondInstall, installed);
  } finally {
    await forceRemove(cwd);
  }
});

