import { test, expect } from 'vitest';
import * as fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { createAgentPluginLifecycle } from '../../index.js';
import { AgentPluginActivationsBusyError } from '../../index.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

// Generalized D1/D2: real filesystem effects, with observations injected through the port.
test('temp file is synced before publication and directory synced afterwards', async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'plugin-durable-'));
  const events: string[] = [];
  const filesystem = {
    ...fs,
    open: async (...args: Parameters<typeof fs.open>) => {
      const handle = await fs.open(...args);
      const sync = handle.sync.bind(handle);
      handle.sync = async () => { events.push(`sync:${path.basename(String(args[0]))}`); await sync(); };
      return handle;
    },
    rename: async (...args: Parameters<typeof fs.rename>) => {
      events.push(`rename:${path.basename(String(args[1]))}`); await fs.rename(...args);
    },
  };
  const api = createAgentPluginLifecycle({ ...ports, filesystem });
  try {
    await api.setAgentPluginActivation({ workspaceRoot: root, pluginId: 'plugin-a', enabled: false, actor: 'operator' });
    const sync = events.findIndex(e => e.startsWith('sync:activations.json.tmp-'));
    const rename = events.indexOf('rename:activations.json');
    expect(sync).toBeGreaterThanOrEqual(0);
    expect(rename).toBeGreaterThan(sync);
    if (process.platform !== 'win32') expect(events.indexOf(`sync:${path.basename(root)}`)).toBeGreaterThan(rename);
    expect((await api.readAgentPluginActivations({ workspaceRoot: root })).plugins['plugin-a']?.enabled).toBe(false);
  } finally { await forceRemove(root); }
});

test('a failed temp sync leaves the recorded decision and removes the temporary file', async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'plugin-sync-fault-'));
  const baseline = createAgentPluginLifecycle(ports);
  try {
    await baseline.setAgentPluginActivation({ workspaceRoot: root, pluginId: 'plugin-a', enabled: false, actor: 'first' });
    const before = await fs.readFile(path.join(root, 'activations.json'), 'utf8');
    const filesystem = { ...fs, open: async (...args: Parameters<typeof fs.open>) => {
      const handle = await fs.open(...args);
      if (String(args[0]).includes('activations.json.tmp-')) handle.sync = async () => { throw new Error('sync failed'); };
      return handle;
    } };
    const api = createAgentPluginLifecycle({ ...ports, filesystem });
    await expect(api.setAgentPluginActivation({ workspaceRoot: root, pluginId: 'plugin-a', enabled: true, actor: 'second' })).rejects.toThrow('sync failed');
    expect(await fs.readFile(path.join(root, 'activations.json'), 'utf8')).toBe(before);
    expect(await fs.readdir(root)).toEqual(['activations.json']);
  } finally { await forceRemove(root); }
});

// REGRESSION: fails if activation returns to token-only ownership checks before publication.
test('a replacement lock inode with identical holder bytes cannot authorize publication', async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'plugin-inode-loss-'));
  const lockPath = path.join(root, 'activations.json.lock');
  const filesystem = { ...fs, open: async (...args: Parameters<typeof fs.open>) => {
    const handle = await fs.open(...args);
    if (String(args[0]).includes('activations.json.tmp-')) {
      const sync = handle.sync.bind(handle);
      handle.sync = async () => {
        await sync();
        const bytes = await fs.readFile(lockPath);
        const replacement = path.join(root, 'replacement.lock');
        await fs.writeFile(replacement, bytes);
        await fs.rename(replacement, lockPath);
      };
    }
    return handle;
  } };
  try {
    const api = createAgentPluginLifecycle({ ...ports, filesystem });
    await expect(api.setAgentPluginActivation({ workspaceRoot: root, pluginId: 'plugin-a', enabled: true, actor: 'operator' }))
      .rejects.toBeInstanceOf(AgentPluginActivationsBusyError);
    await expect(fs.stat(path.join(root, 'activations.json'))).rejects.toMatchObject({ code: 'ENOENT' });
    expect(await fs.readdir(root)).toEqual(['activations.json.lock']);
  } finally { await forceRemove(root); }
});

src/__tests__/folder-zip-node.test.ts.source:
import assert from "node:assert/strict";
import { mkdir, mkdtemp, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "vitest";
import { zipFolderFiles } from "../folder-zip.js";
import { zipLocalFolder } from "../folder-zip-node.js";

test("local folder bytes equal the browser folder upload encoder, including binary and UTF-8 paths", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "folder-zip-"));
  try {
    await mkdir(path.join(root, "images"));
    const binary = new Uint8Array([0x89, 0, 0xff, 0x80]);
    await writeFile(path.join(root, "plugin.json"), "{}");
    await writeFile(path.join(root, "images", "é.png"), binary);
    const files = [new File([binary], "é.png"), new File(["{}"], "plugin.json")];
    Object.defineProperty(files[0], "webkitRelativePath", { value: "picked/images/é.png" });
    Object.defineProperty(files[1], "webkitRelativePath", { value: "picked/plugin.json" });
    const expected = new Uint8Array(await (await zipFolderFiles({ files, maxBytes: 1024 })).arrayBuffer());
    assert.deepEqual(await zipLocalFolder({ path: root, maxBytes: 1024 }), expected);
    assert.deepEqual(await zipLocalFolder({ path: root, maxBytes: 1024 }), expected);
  } finally { await rm(root, { recursive: true, force: true }); }
});

test("local folders refuse empty, missing, raw-size and ZIP-overhead limit violations", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "folder-zip-limits-"));
  try {
    await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), { reason: "empty", message: "That folder is empty." });
    await assert.rejects(() => zipLocalFolder({ path: path.join(root, "missing"), maxBytes: 1024 }), { reason: "unreadable", message: "Could not read that folder. Try again." });
    await writeFile(path.join(root, "a"), "1234567890");
    await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 9 }), { reason: "too-large", message: "Folder is over the upload limit." });
    await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 10 }), { reason: "too-large", message: "Folder is over the upload limit." });
    await writeFile(path.join(root, "b"), "1234567890");
    await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 19 }), { reason: "too-large", message: "Folder is over the upload limit." });
  } finally { await rm(root, { recursive: true, force: true }); }
});

test("local folder collection bounds directory entries as well as files", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "folder-zip-count-"));
  try {
    for (let i = 0; i < 4097; i++) await mkdir(path.join(root, String(i)));
    await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), { reason: "too-many", message: "More than 4096 entries." });
  } finally { await rm(root, { recursive: true, force: true }); }
});

test("local folder collection refuses file and directory symlinks", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "folder-zip-links-"));
  try {
    const folder = path.join(root, "picked");
    await mkdir(folder);
    await writeFile(path.join(root, "outside.txt"), "outside");
    await symlink(path.join(root, "outside.txt"), path.join(folder, "link"));
    await assert.rejects(() => zipLocalFolder({ path: folder, maxBytes: 1024 }), { reason: "unreadable", message: "Could not read that folder. Try again." });
    await rm(path.join(folder, "link"));
    await symlink(root, path.join(folder, "link"));
    await assert.rejects(() => zipLocalFolder({ path: folder, maxBytes: 1024 }), { reason: "unreadable", message: "Could not read that folder. Try again." });
  } finally { await rm(root, { recursive: true, force: true }); }
});

test("a symlink supplied as the root is resolved and accepted (reported, not fixed)", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "folder-zip-root-link-"));
  try {
    const target = path.join(root, "target");
    const link = path.join(root, "link");
    await mkdir(target);
    await writeFile(path.join(target, "a"), "content");
    await symlink(target, link);
    assert.deepEqual(await zipLocalFolder({ path: link, maxBytes: 1024 }), await zipLocalFolder({ path: target, maxBytes: 1024 }));
  } finally { await rm(root, { recursive: true, force: true }); }
});

