/**
 * @file Characterization pins for `../descriptor.ts`, written green on the unmodified parser before
 * the executable-handler fields were added: a surface without them must keep parsing to exactly the
 * same descriptor (no new keys, not even undefined ones), unknown keys stay ignored, and an action
 * without `result` keeps carrying no `result` key.
 */
import { expect, test } from 'vitest';
import { parseAdminSurfacesFile } from '../descriptor.js';

// MOVE: Omitted action effects now normalize to write; optional surface fields still stay absent.
const input = { type: 'object', properties: { name: { type: 'string' } }, required: ['name'] };
const raw = (surface: Record<string, unknown>) => JSON.stringify({ schemaVersion: 1, surfaces: [surface] });
const base = { id: 'settings', title: 'Settings', entry: 'surface/index.html', files: ['surface/app.mjs'], actions: [{ name: 'save', input }] };

test('a surface without handler fields parses to exactly id, title, entry, files, actions and csp', () => {
  expect(parseAdminSurfacesFile({ raw: raw(base) })).toStrictEqual({
    ok: true,
    descriptors: [{ id: 'settings', title: 'Settings', entry: 'surface/index.html', files: ['surface/app.mjs'], actions: [{ name: 'save', effect: 'write', input }], csp: {} }],
  });
});

test('unknown surface keys are ignored, not refused and not copied', () => {
  expect(parseAdminSurfacesFile({ raw: raw({ ...base, colour: 'blue' }) })).toStrictEqual(parseAdminSurfacesFile({ raw: raw(base) }));
});

test('omitted files, actions and csp default to empty', () => {
  const parsed = parseAdminSurfacesFile({ raw: raw({ id: 'settings', title: 'Settings', entry: 'index.html' }) });
  expect(parsed).toStrictEqual({ ok: true, descriptors: [{ id: 'settings', title: 'Settings', entry: 'index.html', files: [], actions: [], csp: {} }] });
});

// Pinned green before the capability declarations (`connections`, `publicConfig`) were added:
// a handled surface that declares neither keeps parsing to exactly its handler fields.
test('a surface with a handler module but no capability declarations parses to exactly its handler fields', () => {
  const handled = { ...base, actions: [{ name: 'save', input, result: input }], handlerModule: 'server/handlers.mjs' };
  expect(parseAdminSurfacesFile({ raw: raw(handled) })).toStrictEqual({
    ok: true,
    descriptors: [{ id: 'settings', title: 'Settings', entry: 'surface/index.html', files: ['surface/app.mjs'], actions: [{ name: 'save', effect: 'write', input, result: input }], csp: {}, handlerModule: 'server/handlers.mjs' }],
  });
});

// Pinned green before `deliveryAdapters` was added: a handled surface that declares connections and
// public config keeps parsing to exactly those keys, so existing descriptors gain no new key.
test('a handled surface with connections and publicConfig parses to exactly its declared fields', () => {
  const handled = { ...base, actions: [{ name: 'save', input, result: input }], handlerModule: 'server/handlers.mjs', connections: [{ id: 'account' }], publicConfig: ['ACME_APP_ID'] };
  expect(parseAdminSurfacesFile({ raw: raw(handled) })).toStrictEqual({
    ok: true,
    descriptors: [{
      id: 'settings', title: 'Settings', entry: 'surface/index.html', files: ['surface/app.mjs'], actions: [{ name: 'save', effect: 'write', input, result: input }], csp: {},
      handlerModule: 'server/handlers.mjs', connections: [{ id: 'account', startParams: [], callbackFields: [] }], publicConfig: ['ACME_APP_ID'],
    }],
  });
});

src/__tests__/vendor-neutrality.test.ts.source:
/**
 * @file Vendor-neutrality pin for the generic seams the first provider plugin is built on: API
 * connections, the installed-app loopback receiver, executable tool contributions and plugin admin
 * surfaces. Those seams must carry opaque plugin/connection/product ids only, so a second provider
 * needs nothing but its own plugin files.
 * This test greps every seam file (sources, READMEs and their tests) for the first provider's
 * vocabulary and fails on any hit, naming file and line. Provider names belong in the plugin.
 */
import { mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterAll, expect, test } from 'vitest';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../..');
const VENDOR_VOCABULARY = /google|googleapis|gsheets|spreadsheet|drive\.file|picker/i;
const SCANNED_EXTENSIONS = new Set(['.ts', '.mts', '.mjs', '.js', '.json', '.md', '.html']);

/** The generic seam files and folders (repo-relative). Folders are scanned recursively. */
const SEAMS = [
  'packages/integrations/src/api-connections',
  'packages/oauth/src/loopback-receiver.ts',
  'packages/oauth/src/loopback-callback.ts',
  'packages/oauth/tests/loopback-receiver.security.test.ts',
  'packages/oauth/tests/loopback-receiver.slice.test.ts',
  'packages/agent-plugins/src/lifecycle',
  'packages/agent-plugins/src/admin-surfaces',
  'packages/plugins/src/host/tool-contributions.ts',
  'packages/plugins/src/host/contributions.ts',
];

/** Every scannable file under `target` (a file or a folder), skipping build output and installs. */
function filesUnder(target: string): string[] {
  if (statSync(target).isFile()) return [target];
  return readdirSync(target, { withFileTypes: true })
    .filter((entry) => entry.name !== 'node_modules' && entry.name !== 'dist')
    .flatMap((entry) => (entry.isDirectory() ? filesUnder(path.join(target, entry.name)) : [path.join(target, entry.name)]))
    .filter((file) => SCANNED_EXTENSIONS.has(path.extname(file)));
}

/** `relative/path:line: text` for every line of `files` that names the vendor vocabulary. */
function vendorHits(files: readonly string[], root: string): string[] {
  return files.flatMap((file) => readFileSync(file, 'utf8').split('\n')
    .flatMap((line, index) => (VENDOR_VOCABULARY.test(line) ? [`${path.relative(root, file)}:${index + 1}: ${line.trim()}`] : [])));
}

const scratch = mkdtempSync(path.join(tmpdir(), 'vendor-neutrality-'));
afterAll(() => rmSync(scratch, { recursive: true, force: true }));

test('the scanner reports a vendor word with its file and line, in any case', () => {
  writeFileSync(path.join(scratch, 'seam.ts'), 'const ok = 1;\n// opens the Picker\n');
  expect(vendorHits(filesUnder(scratch), scratch)).toStrictEqual(['seam.ts:2: // opens the Picker']);
});

test('no generic seam file names the first provider', () => {
  const files = SEAMS.flatMap((seam) => {
    const scanned = filesUnder(path.join(repoRoot, seam));
    // A moved or emptied seam must fail loudly, not pass by scanning nothing.
    expect(scanned.length, `${seam} has no scannable files`).toBeGreaterThan(0);
    return scanned;
  });
  expect(files.length).toBeGreaterThan(40);
  expect(vendorHits(files, repoRoot)).toStrictEqual([]);
});

src/lifecycle/tools/__tests__/definition.source:
/**
 * @file Unit tests for the tool contribution definition: it is an executable definition on the
 * host-chosen filename, imports exactly the declared module, and refuses a module export that is
 * not a tool module, naming the tool and plugin. The import port is a typed fake; nothing runs.
 */
import { describe, expect, test } from 'vitest';
import type { PluginModuleImportPort } from '../../contribution-loader.js';
import type { TrustedPluginPackage } from '../../trusted-plugin-files.js';
import { defineAgentPluginToolContribution } from '../definition.js';
import type { AgentPluginToolDescriptor } from '../manifest.js';

const PLUGIN: TrustedPluginPackage = { pluginId: 'acme-office', packageRoot: '/plugins/acme-office' };
const DESCRIPTOR: AgentPluginToolDescriptor = { name: 'list_rows', description: 'Lists rows.', effect: 'read', module: 'tools/list.mjs', inputSchema: { type: 'object' } };

function load(exported: unknown) {
  const requested: string[] = [];
  const importModule: PluginModuleImportPort = async ({ modulePath }) => { requested.push(modulePath); return { exported }; };
  const definition = defineAgentPluginToolContribution({ filename: 'host-agent-tools.json' });
  return { requested, loaded: definition.load({ plugin: PLUGIN, descriptor: DESCRIPTOR, importModule }) };
}

test('is an executable contribution on the host-chosen filename, parsed by the tools parser', () => {
  const definition = defineAgentPluginToolContribution({ filename: 'host-agent-tools.json' });
  expect(definition).toMatchObject({ filename: 'host-agent-tools.json', contribution: 'agent tools', kind: 'executable' });
  expect(definition.parse({ raw: '{}' })).toEqual({ ok: false, reason: 'schemaVersion must be 1' });
});

describe('module export validation', () => {
  test('a valid tool module loads, importing the declared module path', async () => {
    const module = { invoke: () => 'ok' };
    const { requested, loaded } = load(module);
    await expect(loaded).resolves.toEqual({ descriptor: DESCRIPTOR, pluginId: 'acme-office', module });
    expect(requested).toEqual(['tools/list.mjs']);
  });

  test('a module with a describeAffectedResources function loads', async () => {
    const module = { invoke: () => 'ok', describeAffectedResources: () => ['row 1'] };
    await expect(load(module).loaded).resolves.toMatchObject({ module });
  });

  test('a null export is refused, naming the tool and plugin', async () => {
    await expect(load(null).loaded).resolves.toBe("agent tool 'list_rows' from 'acme-office' was not loaded: its module's default export is not an object");
  });

